git-svn-id: https://svn.apache.org/repos/asf/lucene/dev/trunk@1624370 13f79535-47bb-0310-9956-ffa450edef68

Here is the root cause:
The bug was caused by the `onlyPseudoFields` condition in the `BinaryResponseWriter` class, which did not account for wildcard fields when determining if only pseudo fields were being returned. This oversight led to the Binary Response Writer failing to return fields that matched wildcard patterns in queries.

Here is the patch:

     protected void writeResultsBody( ResultContext res, JavaBinCodec codec ) throws IOException 
     {
       DocList ids = res.docs;
       int sz = ids.size();
       codec.writeTag(JavaBinCodec.ARR, sz);
       if(searcher == null) searcher = solrQueryRequest.getSearcher();
       if(schema == null) schema = solrQueryRequest.getSchema();

       DocTransformer transformer = returnFields.getTransformer();
       TransformContext context = new TransformContext();
       context.query = res.query;
       context.wantsScores = returnFields.wantsScore() && ids.hasScores();
       context.req = solrQueryRequest;
       context.searcher = searcher;
       if( transformer != null ) {
         transformer.setContext( context );
       }

       Set<String> fnames = returnFields.getLuceneFieldNames();
-      boolean onlyPseudoFields = (fnames == null && !returnFields.wantsAllFields())
+      boolean onlyPseudoFields = (fnames == null && !returnFields.wantsAllFields() && !returnFields.hasPatternMatching())
           || (fnames != null && fnames.size() == 1 && SolrReturnFields.SCORE.equals(fnames.iterator().next()));
       context.iterator = ids.iterator();
       for (int i = 0; i < sz; i++) {
         int id = context.iterator.nextDoc();
         SolrDocument sdoc;
         if (onlyPseudoFields) {
           // no need to get stored fields of the document, see SOLR-5968
           sdoc = new SolrDocument();
         } else {
           StoredDocument doc = searcher.doc(id, fnames);
           sdoc = getDoc(doc);
         }
         if( transformer != null ) {
           transformer.transform(sdoc, id);
         }
         codec.writeSolrDocument(sdoc);
       }
       if( transformer != null ) {
         transformer.setContext( null );
       }
     }



